def token_overlap(a, b):
    sa, sb = set(a.split()), set(b.split())
    if not sa or not sb:
        return 0.0
    return len(sa & sb) / len(sa | sb)

test_prompts = ["what is the capital of France", "how to sort a list in python"]
train_corpus = [
    "python is a programming language",
    "how to sort a list in python use the sorted function",
    "the capital of France is Paris",
    "machine learning needs data",
]
contaminated = 0
for t in test_prompts:
    if any(token_overlap(t, c) >= 0.5 for c in train_corpus):
        contaminated += 1
print(f"污染率: {contaminated}/{len(test_prompts)} = {contaminated/len(test_prompts):.2f}")
